import{_ as o,o as a,c as s,ae as t}from"./chunks/framework.Dn6zxbF8.js";const h=JSON.parse('{"title":"Language workspaces","description":"","frontmatter":{"id":"5842232571","title":"Language workspaces","state":"Draft","created":"2026-11-01T00:00:00.000Z","tags":["directory","monorepo","rust","go","typescript","elixir","python"],"category":"Platform"},"headers":[],"relativePath":"adrs/5842232571/README.md","filePath":"adrs/5842232571/README.md"}'),n={name:"adrs/5842232571/README.md"};function r(c,e,i,l,d,p){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="language-workspaces" tabindex="-1">Language workspaces <a class="header-anchor" href="#language-workspaces" aria-label="Permalink to &quot;Language workspaces&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><a href="./../9316364013/README.html">ADR#9316364013</a> reserves the directories that belong to no single language workspace, but it does not say where a language workspace itself lives. A repository that ships a Rust server next to a Go client, an Elixir client and a TypeScript console has to place several toolchains, each with its own manifest, lockfile and tool configuration.</p><p>A survey of our repositories found most multi-language repositories already converged on one root directory per toolchain named <code>&lt;language&gt;workspace/</code>: <code>rsworkspace/</code>, <code>goworkspace/</code>, <code>tsworkspace/</code>, <code>pyworkspace/</code>. The language part drifted where nothing fixed it: <code>rustworkspace/</code> next to <code>go-workspace/</code> in one repository, <code>elixirworkspace/</code> next to <code>rsworkspace/</code> in others. Single-language Rust repositories kept the Cargo workspace at the root.</p><p>The language part is fixed here as the language&#39;s source file extension, so a new language never needs a naming decision.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><ul><li><p>You <strong>MUST</strong> place each language toolchain of a repository with source in more than one language in its own root directory named <code>&lt;extension&gt;workspace/</code>, where <code>&lt;extension&gt;</code> is the language&#39;s source file extension without the dot:</p><table tabindex="0"><thead><tr><th>Language</th><th>Directory</th></tr></thead><tbody><tr><td>Rust</td><td><code>rsworkspace/</code></td></tr><tr><td>Go</td><td><code>goworkspace/</code></td></tr><tr><td>TypeScript</td><td><code>tsworkspace/</code></td></tr><tr><td>Elixir</td><td><code>exworkspace/</code></td></tr><tr><td>Python</td><td><code>pyworkspace/</code></td></tr><tr><td>Kotlin</td><td><code>ktworkspace/</code></td></tr><tr><td>Swift</td><td><code>swiftworkspace/</code></td></tr></tbody></table></li><li><p>You <strong>MUST NOT</strong> spell the language out or separate the words: <code>rustworkspace/</code>, <code>elixirworkspace/</code>, <code>go-workspace/</code> and <code>go_workspace/</code> are wrong.</p></li><li><p>You <strong>MUST NOT</strong> use a bare language name (<code>rust/</code>, <code>go/</code>, <code>elixir/</code>) or a role name (<code>clients/</code>, <code>sdks/</code>, <code>packages/</code>, <code>apps/</code>) at the repository root for source a toolchain builds.</p></li><li><p>You <strong>MAY</strong> keep the toolchain at the repository root while the repository has source in one language only. You <strong>MUST</strong> move it into its workspace when a second language arrives.</p></li><li><p>You <strong>MUST</strong> make each workspace the root of exactly one toolchain: its manifest and lockfile sit directly in it, such as <code>Cargo.toml</code> and <code>Cargo.lock</code>, <code>go.mod</code> or <code>go.work</code>, <code>mix.exs</code> and <code>mix.lock</code>, <code>pnpm-workspace.yaml</code> and <code>pnpm-lock.yaml</code>, <code>pyproject.toml</code> and <code>uv.lock</code>.</p></li><li><p>You <strong>SHOULD</strong> set the workspace up with the toolchain&#39;s own multi-package mechanism, such as a Cargo workspace, a <code>go.work</code> file, a pnpm workspace, a Mix umbrella, a uv workspace or a Gradle multi-project build, with each package in its own directory, even while it holds a single package. A second package then joins the workspace instead of reshaping it. You <strong>MAY</strong> place a single package directly at the workspace root, such as a single Cargo package whose <code>Cargo.toml</code> declares no <code>[workspace]</code> members.</p></li><li><p>You <strong>MUST</strong> keep configuration read by one toolchain only, such as <code>clippy.toml</code>, <code>deny.toml</code>, <code>rustfmt.toml</code>, <code>rust-toolchain.toml</code>, <code>.golangci.yaml</code>, <code>.formatter.exs</code> and <code>tsconfig.base.json</code>, in that workspace and <strong>MUST NOT</strong> keep it at the repository root. Configuration for a tool that reads the whole repository goes under <code>.config/&lt;tool&gt;/</code>.</p></li><li><p>You <strong>MUST</strong> keep everything a workspace owns inside it, including database migrations its code embeds, test fixtures and examples.</p></li><li><p>You <strong>MUST NOT</strong> carry a copy of a directory reserved by <a href="./../9316364013/README.html">ADR#9316364013</a> inside a workspace. The workspace uses the copy its project nests per <a href="./../0752163629/README.html">ADR#0752163629</a> when there is one, and the repository root copy otherwise.</p></li><li><p>You <strong>MUST</strong> place the members of a Cargo workspace under <code>crates/&lt;crate&gt;/</code> relative to the workspace directory, which is <code>rsworkspace/crates/&lt;crate&gt;/</code> for the root project and <code>projects/&lt;project&gt;/rsworkspace/crates/&lt;crate&gt;/</code> for a named one. You <strong>MUST</strong> follow the toolchain&#39;s own layout inside every other workspace.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.</span></span>
<span class="line"><span>├── .github/</span></span>
<span class="line"><span>├── .config/&lt;tool&gt;/</span></span>
<span class="line"><span>├── devops/</span></span>
<span class="line"><span>├── docs/</span></span>
<span class="line"><span>├── proto/</span></span>
<span class="line"><span>├── otel/</span></span>
<span class="line"><span>├── rsworkspace</span></span>
<span class="line"><span>│   ├── Cargo.toml</span></span>
<span class="line"><span>│   ├── Cargo.lock</span></span>
<span class="line"><span>│   ├── clippy.toml</span></span>
<span class="line"><span>│   ├── deny.toml</span></span>
<span class="line"><span>│   └── crates/&lt;crate&gt;/</span></span>
<span class="line"><span>├── goworkspace</span></span>
<span class="line"><span>│   ├── go.work</span></span>
<span class="line"><span>│   └── &lt;module&gt;/go.mod</span></span>
<span class="line"><span>├── exworkspace</span></span>
<span class="line"><span>│   ├── mix.exs           # umbrella</span></span>
<span class="line"><span>│   ├── mix.lock</span></span>
<span class="line"><span>│   └── apps/&lt;app&gt;/</span></span>
<span class="line"><span>└── LICENSE</span></span></code></pre></div></li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The <code>module</code> directive in <code>go.mod</code> sets a Go module&#39;s import path, not its directory. A module at <code>goworkspace/&lt;module&gt;/</code> whose path matches its location is imported as <code>github.com/&lt;org&gt;/&lt;repo&gt;/goworkspace/&lt;module&gt;</code> and tags its releases <code>goworkspace/&lt;module&gt;/vX.Y.Z</code>. A repository that publishes a Go module for others to import decides that path before the first release, because changing it later breaks every importer.</li><li>Existing <code>rustworkspace/</code>, <code>go-workspace/</code>, <code>elixirworkspace/</code> and <code>kotlinworkspace/</code> directories are renamed. The rename touches the paths in CI, container builds and mise tasks, and nothing else.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="./../9316364013/README.html">ADR#9316364013</a>: Reserved repository directories</li><li><a href="./../4711775939/README.html">ADR#4711775939</a>: Schema source directories</li><li><a href="./../2078011537/README.html">ADR#2078011537</a>: Operational assets</li><li><a href="./../0752163629/README.html">ADR#0752163629</a>: Project namespaces</li><li><a href="./../1631648331/README.html">ADR#1631648331</a>: Rust is the language for new services and programs</li></ul>`,11)])])}const u=o(n,[["render",r]]);export{h as __pageData,u as default};
